import sys

def is_regular_sequence(s, k):
    n = len(s)
    result = [0] * n

    for i in range(1, n + 1):
        if i % (2 * k + 1) == 0:
            A = s[:i // (2 * k + 1)]
            B = s[i // (2 * k + 1):2 * i // (2 * k + 1)]
            pattern = A + B
            if pattern * (k + 1) == s[:i]:
                result[i - 1] = 1

    return ''.join(map(str, result))

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    s = data[2]

    print(is_regular_sequence(s, k))

if __name__ == "__main__":
    main()
